alter table shift_templates add column if not exists day_group text not null default 'all_days';
alter table shift_templates add column if not exists crosses_midnight boolean not null default false;
alter table shift_templates add column if not exists scheduled_hours numeric(5,2);
update shift_templates set crosses_midnight=ends_at<=starts_at,scheduled_hours=round((case when ends_at<=starts_at then extract(epoch from((date '2000-01-02'+ends_at)-(date '2000-01-01'+starts_at)))else extract(epoch from(ends_at-starts_at))end/3600)::numeric,2) where scheduled_hours is null;
alter table shift_templates alter column scheduled_hours set not null;
alter table shift_templates drop constraint if exists shift_scheduled_hours_positive;
alter table shift_templates add constraint shift_scheduled_hours_positive check(scheduled_hours>0 and scheduled_hours<=24);
create table capacity_profiles(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),name text not null,production_area_id uuid not null references production_areas(id),shift_template_id uuid not null references shift_templates(id),resource_count numeric(8,2) not null check(resource_count>=0),machine_count numeric(8,2) check(machine_count>=0),scheduled_hours numeric(5,2) not null check(scheduled_hours>0 and scheduled_hours<=24),hourly_rate numeric(12,3) not null check(hourly_rate>=0),efficiency numeric(6,4) not null check(efficiency between 0 and 1),work_days numeric(4,2) not null default 5 check(work_days between 0 and 7),active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,name));
create table capacity_scenarios(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),name text not null,notes text,created_by uuid,created_by_email text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,name));
create table capacity_scenario_lines(id uuid primary key default gen_random_uuid(),capacity_scenario_id uuid not null references capacity_scenarios(id) on delete cascade,production_area_id uuid not null references production_areas(id),shift_template_id uuid not null references shift_templates(id),resource_count numeric(8,2) not null check(resource_count>=0),machine_count numeric(8,2) check(machine_count>=0),scheduled_hours numeric(5,2) not null check(scheduled_hours>0 and scheduled_hours<=24),hourly_rate numeric(12,3) not null check(hourly_rate>=0),efficiency numeric(6,4) not null check(efficiency between 0 and 1),work_days numeric(4,2) not null default 5 check(work_days between 0 and 7),calculated_capacity numeric(14,3) generated always as(resource_count*scheduled_hours*hourly_rate*efficiency) stored);
create index capacity_profiles_context_idx on capacity_profiles(organization_id,production_area_id,shift_template_id) where active;create index capacity_scenario_lines_scenario_idx on capacity_scenario_lines(capacity_scenario_id);
alter table capacity_profiles enable row level security;alter table capacity_scenarios enable row level security;alter table capacity_scenario_lines enable row level security;revoke all on capacity_profiles,capacity_scenarios,capacity_scenario_lines from anon,authenticated;grant select,insert,update,delete on capacity_profiles,capacity_scenarios,capacity_scenario_lines to service_role;
create or replace view v_capacity_load with(security_invoker=true)as with demand as(select organization_id,line area_code,sum(remaining_units)demand_units from v_production_planning where coalesce(planning_status,'unplanned')not in('completed','cancelled')group by organization_id,line),capacity as(select p.organization_id,a.code area_code,sum(p.resource_count*p.scheduled_hours*p.hourly_rate*p.efficiency)daily_capacity,sum(p.resource_count*p.scheduled_hours*p.hourly_rate*p.efficiency*p.work_days)weekly_capacity from capacity_profiles p join production_areas a on a.id=p.production_area_id where p.active group by p.organization_id,a.code)select c.organization_id,c.area_code,coalesce(d.demand_units,0)demand_units,c.daily_capacity,c.weekly_capacity,case when c.daily_capacity=0 then null else round(coalesce(d.demand_units,0)/c.daily_capacity*100,2)end load_percent,c.daily_capacity-coalesce(d.demand_units,0)capacity_gap,case when c.daily_capacity=0 then null else round(coalesce(d.demand_units,0)/c.daily_capacity,2)end relative_lead_days from capacity c left join demand d using(organization_id,area_code);revoke all on v_capacity_load from anon,authenticated;grant select on v_capacity_load to service_role;
create or replace function resolve_production_date(p_event_at timestamptz,p_starts_at time,p_ends_at time,p_timezone text default'Australia/Brisbane')returns date language sql immutable as $$select case when p_ends_at<=p_starts_at and(p_event_at at time zone p_timezone)::time<p_ends_at then(p_event_at at time zone p_timezone)::date-1 else(p_event_at at time zone p_timezone)::date end$$;revoke all on function resolve_production_date(timestamptz,time,time,text)from public,anon,authenticated;grant execute on function resolve_production_date(timestamptz,time,time,text)to service_role;
